INSERT INTO `categories` (`id`, `title`, `title_jp`, `slug`, `summary`, `summary_jp`, `photo`, `is_parent`, `parent_id`, `added_by`, `status`, `catgenres`, `created_at`, `updated_at`) VALUES
(1, 'Anime & Manga', 'アニメ・マンガ', 'anime_manga', 'Anime & Manga Art brings expressive characters, emotional storytelling, and vibrant Japanese animation aesthetics to life. From quiet slice-of-life moments to dramatic scenes, each piece captures the charm and energy of anime culture.', 'アニメ・マンガアートは、表情豊かなキャラクターと感動的なストーリーを描く日本のアニメ文化の魅力を表現します。日常の一コマから劇的なシーンまで、多彩な世界観をお楽しみいただけます。', '/storage/photos/category/1.webp', 1, NULL, NULL, 'active', 1, NULL, NULL),
(2, 'Pixel Art', 'ピクセルアート', 'pixel_art', 'Pixel Art celebrates the charm of retro video games through carefully placed pixels, limited palettes, and nostalgic 8-bit and 16-bit aesthetics. Each artwork transforms simple squares into detailed, atmospheric scenes full of personality.', 'ピクセルアートは、レトロゲームの魅力をドット単位の緻密な表現で再現します。8ビット・16ビットの懐かしい美学を通じて、シンプルな四角形から生き生きとした世界を生み出します。', '/storage/photos/category/2.webp', 1, NULL, NULL, 'active', 1, NULL, NULL),
(3, 'Pop Art', 'ポップアート', 'pop_art', 'Pop Art transforms everyday objects, icons, and consumer culture into bold, colorful statements. With halftone dots, comic-style panels, and vivid contrasts, this collection celebrates the playful spirit of popular culture.', 'ポップアートは、日常のモノやアイコン、大衆文化を大胆で色彩豊かな作品へと変換します。ハーフトーンやコミック調の表現で、ポップカルチャーの遊び心を表現します。', '/storage/photos/category/3.webp', 1, NULL, NULL, 'active', 1, NULL, NULL),
(4, 'Street Art', 'ストリートアート', 'street_art', 'Street Art captures the raw energy of urban creativity — graffiti lettering, stencil work, and mural-inspired compositions. Each piece brings the rebellious, expressive spirit of city walls into digital form.', 'ストリートアートは、グラフィティやステンシル、壁画から着想を得た都市の創造性を表現します。街の壁に息づく自由で反骨的な精神をデジタル作品として届けます。', '/storage/photos/category/4.webp', 1, NULL, NULL, 'active', 1, NULL, NULL),
(5, 'Ukiyo-e Modern', '現代浮世絵', 'ukiyoe_modern', 'Ukiyo-e Modern reimagines traditional Japanese woodblock printing for the contemporary world. Classic techniques, flowing lines, and iconic motifs meet modern city life, blending centuries of heritage with today\'s imagination.', '現代浮世絵は、伝統的な木版画の技法を現代の視点で再解釈するコレクションです。流れるような線と古典的なモチーフが現代の都市生活と融合し、新しい美の世界を描きます。', '/storage/photos/category/5.webp', 1, NULL, NULL, 'active', 1, NULL, NULL);
INSERT INTO `products` (`id`, `title`, `title_jp`, `slug`, `summary`, `summary_jp`, `description`, `description_jp`, `meta_title`, `meta_description`, `meta_keyword`, `photo`, `stock`, `size`, `condition`, `status`, `price`, `price_in_points`, `price_jp`, `price_hk`, `discount`, `is_featured`, `extra_description`, `extra_description_jp`, `cat_id`, `child_cat_id`, `brand_id`, `duration`, `skill_level`, `skill_level_jp`, `lectures`, `language`, `language_jp`, `genres`, `created_at`, `updated_at`) VALUES
(1, 'Sakura Schoolyard Daydream', '桜舞う校庭の白昼夢', 'sakura-schoolyard-daydream', 'An anime-style scene of a student daydreaming beneath falling cherry blossoms in a quiet schoolyard.', '静かな校庭で桜の花びらが舞う中、物思いにふける学生を描いたアニメ風作品。', 'This heartfelt anime illustration captures a fleeting moment of youth: a lone student leaning against a school fence as cherry blossom petals drift through golden afternoon light. The soft cel-shaded rendering, gentle gradients of pink and cream, and carefully placed lens flares evoke the bittersweet nostalgia of graduation season. Background details — a distant clock tower, bicycles by the gate, uniforms fluttering in the breeze — ground the dreamlike atmosphere in everyday school life. The composition uses shallow depth of field to keep the viewer\'s eye on the character\'s wistful expression, telling an entire coming-of-age story in a single frame. Perfect for fans of slice-of-life anime aesthetics and anyone who treasures the quiet poetry of spring.', '桜の花びらが舞う放課後の校庭で、フェンスにもたれて物思いにふける学生の姿を描いた作品です。柔らかなセル画調の彩色と淡いピンクの色彩が、卒業シーズンの切ない郷愁を表現しています。時計台や自転車などの背景描写が、日常と夢の狭間の空気感を演出します。青春の一瞬を切り取った、日常系アニメファンに贈る一枚です。', 'Sakura Schoolyard Daydream', 'Anime-style cherry blossom schoolyard artwork capturing youth and springtime nostalgia', 'anime schoolyard art, sakura anime illustration, cherry blossom digital art, slice of life anime print, japanese school anime scene', 'storage/photos/products/1.webp', 999999, NULL, NULL, 'active', 35.00, 35, 35.00, 35.00, 0.00, 1, '', '', 1, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(2, 'Midnight Ramen Stand', '真夜中のラーメン屋台', 'midnight-ramen-stand', 'A cozy anime night scene of a glowing ramen stand serving a lone customer under lantern light.', '提灯の明かりの下、一人の客を迎える温かなラーメン屋台を描いた夜のアニメシーン。', 'Steam rises from a bowl of ramen as a tired salaryman finds comfort at a small street stall, its red lanterns glowing warmly against the deep blue of midnight. This anime-style piece celebrates the intimate, cinematic atmosphere of late-night Japan: wet pavement reflecting lantern light, a friendly cook behind the counter, and menus handwritten on wooden boards. The color story contrasts cool nighttime blues with the inviting orange glow of the stall, creating a pocket of warmth in the sleeping city. Every prop — chopstick holders, hanging noren curtains, a sleeping cat on a nearby crate — is rendered with affectionate detail. A comforting artwork for anyone who loves anime food scenes and the quiet magic of the city after dark.', '深夜の街角、赤提灯の温かな光に包まれたラーメン屋台で一杯のラーメンを味わうサラリーマンを描いた作品です。濡れた路面に映る光、暖簾、手書きのメニューなど、日本の夜の情緒を丁寧に表現しました。冷たい夜の青と屋台の温かなオレンジの対比が、都会の中の小さな安らぎを演出します。アニメの食事シーンが好きな方に贈る癒しの一枚です。', 'Midnight Ramen Stand', 'Cozy anime night artwork of a glowing ramen street stall in midnight Japan', 'anime ramen art, japanese street food illustration, night anime scene, cozy anime artwork, lantern night digital art', 'storage/photos/products/2.webp', 999999, NULL, NULL, 'active', 38.00, 38, 38.00, 38.00, 0.00, 1, '', '', 1, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(3, 'The Shrine Maiden\'s Umbrella', '巫女と和傘', 'the-shrine-maidens-umbrella', 'A shrine maiden with a red paper umbrella walks through rain at an old torii gate, in delicate anime style.', '雨の中、赤い和傘を差して古い鳥居をくぐる巫女を描いた繊細なアニメ作品。', 'Rain falls softly around a shrine maiden as she passes beneath a weathered torii gate, her crimson paper umbrella the single point of vivid color in a misty landscape of greys and greens. This anime illustration blends traditional Japanese imagery with modern animation techniques: delicate rain streaks, glossy stone steps, and translucent umbrella lighting rendered with painterly care. Her white and red vestments echo the umbrella and gate, tying the composition together in a harmonious color ritual. The mood is serene and slightly mysterious, hinting at stories of guardianship and old spirits without showing them directly. A refined piece for collectors drawn to traditional aesthetics filtered through the anime lens.', '霧に包まれた参道で、赤い和傘を差して鳥居をくぐる巫女の姿を描いた作品です。灰色と緑の風景の中で、傘の紅一点が印象的なアクセントとなっています。雨の筋や濡れた石段、傘越しの光など、繊細な描写が静謐で神秘的な雰囲気を醸し出します。伝統とアニメ表現が融合した、上品な一枚です。', 'Shrine Maiden Umbrella Art', 'Anime shrine maiden with red umbrella in the rain at a torii gate', 'shrine maiden anime art, torii gate illustration, japanese umbrella artwork, rainy anime scene, miko digital art', 'storage/photos/products/3.webp', 999999, NULL, NULL, 'active', 42.00, 42, 42.00, 42.00, 0.00, 0, '', '', 1, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(4, 'Rooftop Confession at Dusk', '夕暮れの屋上の告白', 'rooftop-confession-at-dusk', 'Two anime characters share a quiet moment on a school rooftop as the sky burns orange and violet.', 'オレンジと紫に染まる空の下、学校の屋上で静かな時を過ごす二人を描いたアニメ作品。', 'The chain-link fence, the water tank, the endless gradient sky — every beloved trope of the anime rooftop scene comes together in this emotionally charged illustration. Two figures stand a careful distance apart as dusk paints the horizon in molten orange fading to deep violet, the city below already twinkling awake. Long shadows and backlit hair rim-lighting heighten the drama of a conversation we cannot hear but instantly understand. The composition leaves generous negative space in the sky, letting the emotional weight breathe. It is a tribute to the golden-hour confessions that define romance anime, rendered with cinematic lighting and tender restraint. Ideal for fans of romantic and coming-of-age anime storytelling.', '金網フェンス、給水タンク、グラデーションの空——アニメの屋上シーンの魅力を凝縮した感動的な一枚です。夕焼けがオレンジから深い紫へと移ろう中、少し距離を置いて佇む二人のシルエットが切ない物語を語ります。逆光に輝く髪や長く伸びる影が、聞こえない会話の緊張感を演出します。恋愛アニメや青春アニメが好きな方に贈る作品です。', 'Rooftop Confession Anime Art', 'Romantic anime rooftop scene at dusk with cinematic sunset lighting', 'anime rooftop scene, sunset anime art, romantic anime illustration, school anime artwork, dusk confession art', 'storage/photos/products/4.webp', 999999, NULL, NULL, 'active', 36.00, 36, 36.00, 36.00, 0.00, 0, '', '', 1, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(5, 'Neon Idol Stage Debut', 'ネオンアイドルのステージデビュー', 'neon-idol-stage-debut', 'A vibrant anime idol performs her first concert amid stage lights, glowsticks, and falling confetti.', 'ステージライトとペンライト、舞う紙吹雪の中で初ライブを飾るアニメアイドルを描いた作品。', 'Confetti rains down as a young idol hits the final note of her debut song, arms outstretched toward an ocean of glowsticks. This high-energy anime illustration channels the euphoria of idol culture: dynamic stage lighting in magenta and cyan, motion-blurred ribbons, and a costume glittering with rhinestone detail. The low camera angle makes the viewer part of the audience, looking up at a star being born. Careful subsurface lighting on the character\'s face captures both exhilaration and nervous tears — the emotional core beneath the spectacle. Speed lines and particle effects borrowed from animation production give the still image a sense of unstoppable momentum. A must-have for fans of idol anime and concert culture.', '紙吹雪が舞い散るステージで、デビュー曲のラストを歌い上げるアイドルを描いたエネルギッシュな作品です。マゼンタとシアンの照明、揺れるペンライトの海、輝く衣装がライブの熱狂を伝えます。ローアングルの構図により、観客席から新星の誕生を見上げるような臨場感を演出。興奮と感動の涙が入り混じる表情が、この作品の感情的な核となっています。アイドルアニメファン必見の一枚です。', 'Neon Idol Stage Debut', 'High-energy anime idol concert artwork with stage lights and confetti', 'anime idol art, concert anime illustration, idol stage artwork, glowstick anime scene, japanese idol digital art', 'storage/photos/products/5.webp', 999999, NULL, NULL, 'active', 40.00, 40, 40.00, 40.00, 0.00, 1, '', '', 1, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(6, 'Summer Festival Fireworks', '夏祭りの花火', 'summer-festival-fireworks', 'An anime scene of friends in yukata watching fireworks bloom over a riverside summer festival.', '川辺の夏祭りで、浴衣姿の友人たちが夜空に咲く花火を見上げるアニメシーン。', 'Chrysanthemum fireworks bloom across the night sky as festivalgoers in colorful yukata pause between food stalls to look up in wonder. This anime illustration is a love letter to the Japanese summer festival: goldfish-scooping booths, strings of paper lanterns, candy-apple stands, and the river below catching every burst of light in rippling reflections. The characters are drawn mid-laughter, hand fans raised, capturing the communal joy that defines matsuri nights. A warm palette of lantern reds and oranges grounds the scene while the fireworks explode in cool blues, purples, and greens overhead. Rich environmental storytelling and nostalgic detail make this a centerpiece for any anime art collection.', '夜空に大輪の花火が咲く中、浴衣姿の人々が屋台の間で足を止めて見上げる夏祭りの一場面です。金魚すくい、提灯の列、りんご飴の屋台、花火を映す川面など、日本の夏の風物詩を細部まで描き込みました。提灯の暖色と花火の寒色の対比が、祭りの夜の高揚感を表現します。懐かしさあふれる、アニメアートコレクションの主役となる一枚です。', 'Summer Festival Fireworks', 'Anime summer festival artwork with fireworks, yukata, and lantern-lit stalls', 'anime fireworks art, summer festival illustration, yukata anime scene, matsuri digital art, japanese festival artwork', 'storage/photos/products/6.webp', 999999, NULL, NULL, 'active', 44.00, 44, 44.00, 44.00, 0.00, 0, '', '', 1, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(7, '8-Bit Tavern Nights', '8ビットの酒場の夜', '8-bit-tavern-nights', 'A cozy pixel art tavern filled with adventurers, flickering torchlight, and RPG nostalgia.', '冒険者たちが集う、松明の灯りが揺れるレトロRPG風ピクセルアートの酒場。', 'Step into a pixel-perfect fantasy tavern where knights clink mugs, a bard strums by the fireplace, and a hooded stranger waits in the corner booth. Built on a warm 16-color palette, this artwork recreates the beloved atmosphere of classic role-playing games — dithered torchlight, chunky wooden beams, and sprite characters bursting with personality despite their tiny scale. Every table tells a micro-story: dice mid-roll, a treasure map half unfurled, a cat sleeping beside the ale barrels. The careful pixel clustering and hand-placed highlights honor the craft of retro game artists while pushing scene density beyond what old hardware allowed. A nostalgic gathering place rendered one pixel at a time, ideal for RPG lovers and retro gamers alike.', '騎士たちがジョッキを交わし、暖炉のそばで吟遊詩人が歌う、ファンタジーRPGの酒場をドット絵で再現した作品です。温かみのある16色パレットと緻密なドット配置で、レトロゲームの世界観を忠実に表現しました。サイコロ、宝の地図、樽のそばで眠る猫など、各テーブルに小さな物語が息づいています。RPGファンとレトロゲーマーに贈る一枚です。', '8-Bit Tavern Nights', 'Retro pixel art fantasy tavern scene inspired by classic RPG games', 'pixel art tavern, retro rpg artwork, 8bit fantasy art, pixel game illustration, retro gaming digital art', 'storage/photos/products/7.webp', 999999, NULL, NULL, 'active', 30.00, 30, 30.00, 30.00, 0.00, 1, '', '', 2, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(8, 'Pixel Metropolis Sunset', 'ピクセル大都会の夕暮れ', 'pixel-metropolis-sunset', 'A sprawling pixel art cityscape glowing under a gradient sunset, alive with tiny animated stories.', 'グラデーションの夕焼けに染まる大都会を、無数の小さな物語と共に描いたピクセルアート。', 'Hundreds of hand-placed windows light up one by one as the sun sinks behind a pixel art skyline rendered in luscious sunset gradients. Rooftop gardens, laundry lines, train cars gliding along elevated tracks, and pedestrians the size of a few pixels give this metropolis its heartbeat. The artwork uses classic dithering to blend orange into pink into dusky purple, a technique borrowed from 16-bit era masterpieces and elevated with modern color theory. Look closely and micro-narratives emerge everywhere: a couple on a balcony, a delivery rider racing the last light, pigeons scattering from an antenna. It is a city you can explore for minutes and still find something new — the enduring magic of detailed pixel work.', '夕日が沈むにつれ、無数の窓に一つずつ明かりが灯るピクセルアートの大都会。屋上庭園、洗濯物、高架を走る電車、数ドットの通行人たちが街に鼓動を与えます。16ビット時代の名作に学んだディザリング技法で、オレンジからピンク、紫へと移ろう空を表現しました。バルコニーの恋人や配達員など、見るたびに新しい発見がある作品です。', 'Pixel Metropolis Sunset', 'Detailed pixel art city skyline at sunset with hidden micro-stories', 'pixel art city, pixel sunset artwork, retro cityscape art, 16bit skyline illustration, pixel metropolis print', 'storage/photos/products/8.webp', 999999, NULL, NULL, 'active', 34.00, 34, 34.00, 34.00, 0.00, 1, '', '', 2, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(9, 'Dungeon Crawler\'s Rest', 'ダンジョン探索者の休息', 'dungeon-crawlers-rest', 'A pixel art hero rests at a save-point campfire deep inside a mysterious glowing dungeon.', '神秘的なダンジョンの奥深く、セーブポイントの焚き火で休む勇者を描いたドット絵作品。', 'Deep beneath the earth, a weary adventurer sits beside a campfire whose pixel flames cast dancing orange light across mossy stone walls. Glowing blue crystals, a floating save-point icon, and a sleeping slime companion complete this affectionate homage to dungeon-crawler games. The limited palette — cool cave blues pierced by warm firelight — demonstrates the expressive power of constraint that defines great pixel art. Equipment details reward close viewing: a dented shield, potion bottles catching the light, a map scrawled with dead ends. The scene captures a feeling every gamer knows — the peaceful pause before the next boss room — and preserves it as a quiet, glowing memory.', '地下深くのダンジョンで、焚き火のそばに腰を下ろす疲れた冒険者。苔むした石壁に揺れる炎の光、青く輝くクリスタル、浮かぶセーブポイント、眠るスライムの相棒が、ダンジョンRPGへの愛を込めて描かれています。洞窟の青と焚き火の暖色の対比が、ドット絵ならではの表現力を示します。次のボス戦の前の静かな休息——ゲーマーなら誰もが知るあの瞬間を閉じ込めた作品です。', 'Dungeon Crawler\'s Rest', 'Pixel art campfire rest scene in a glowing dungeon, retro RPG style', 'pixel dungeon art, campfire pixel artwork, retro rpg rest scene, 8bit adventurer art, dungeon crawler illustration', 'storage/photos/products/9.webp', 999999, NULL, NULL, 'active', 32.00, 32, 32.00, 32.00, 0.00, 0, '', '', 2, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(10, 'Retro Arcade Heartbeat', 'レトロアーケードの鼓動', 'retro-arcade-heartbeat', 'A pixel art arcade packed with glowing cabinets, high scores, and 1980s neon energy.', '光り輝く筐体とハイスコア、80年代の熱気に満ちたゲームセンターを描いたピクセルアート。', 'Rows of arcade cabinets blaze with attract-mode demos as kids crowd around the machine where someone is one level from the high score. This pixel artwork bottles the electric atmosphere of the golden age of arcades: carpet patterns in impossible geometry, a change machine spitting tokens, prize counters stuffed with plush toys, and CRT glow rendered through careful pixel-level bloom. Each cabinet screen shows a tiny original game, a playful nod to the classics without copying any of them. The palette leans into deep purples and blacks so the screen light does the storytelling. For anyone who remembers spending an entire allowance one quarter at a time, this piece is pure time travel.', 'デモ画面が光るアーケード筐体の列、ハイスコアに挑む一台を囲む子どもたち。黄金期のゲームセンターの熱気をドット絵で封じ込めた作品です。幾何学模様のカーペット、メダル両替機、ぬいぐるみの景品カウンター、ブラウン管の光まで、ピクセル単位で丁寧に描写しました。深い紫と黒を基調に、画面の光が物語を語ります。ゲームセンターに通った思い出を持つすべての人への、時間旅行の一枚です。', 'Retro Arcade Heartbeat', 'Pixel art retro arcade scene with glowing game cabinets and 80s atmosphere', 'pixel arcade art, retro arcade illustration, 80s gaming artwork, pixel cabinet art, arcade nostalgia print', 'storage/photos/products/10.webp', 999999, NULL, NULL, 'active', 33.00, 33, 33.00, 33.00, 0.00, 0, '', '', 2, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(11, 'Isometric Island Farm', 'アイソメトリックの島の農場', 'isometric-island-farm', 'A charming isometric pixel art farm island with crops, animals, and a tiny thriving homestead.', '作物や動物たちと共に営まれる小さな農場の島を、アイソメトリック視点で描いたドット絵。', 'Floating gently in a pastel sea, this isometric island holds an entire farming life in miniature: neat rows of pixel crops in four seasons of growth, a red-roofed farmhouse with smoke curling from the chimney, chickens scattered mid-peck, and an orchard heavy with fruit. The isometric perspective — beloved by simulation and farming games — lets every element sit in satisfying, readable order, like a diorama you could reach into. Soft shadows and a sun-washed palette give the scene its gentle optimism. Tiny details reward exploration: a scarecrow wearing a flower, a dog asleep on the porch, a rowboat tied to the dock waiting for market day. Wholesome, meticulous, and quietly joyful.', 'パステル色の海に浮かぶ小さな島に、農場の暮らしのすべてが詰まっています。整然と並ぶ作物、煙突から煙が立ちのぼる赤い屋根の農家、餌をついばむニワトリ、実りの果樹園。シミュレーションゲームで愛されるアイソメトリック視点が、ジオラマのような心地よい秩序を生み出します。花を飾ったかかし、ポーチで眠る犬など、細部の発見も楽しい、温かく丁寧な作品です。', 'Isometric Island Farm', 'Cozy isometric pixel art farm island with crops, animals, and farmhouse', 'isometric pixel art, pixel farm illustration, cozy game artwork, farming island art, isometric digital print', 'storage/photos/products/11.webp', 999999, NULL, NULL, 'active', 36.00, 36, 36.00, 36.00, 0.00, 1, '', '', 2, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(12, 'Pixel Rain at the Bus Stop', 'バス停のピクセル雨', 'pixel-rain-at-the-bus-stop', 'A quiet, moody pixel art scene of a lone figure waiting at a rainy nighttime bus stop.', '雨の夜、バス停で一人静かにバスを待つ人物を描いた叙情的なピクセルアート。', 'Rain falls in single-pixel streaks past a humming fluorescent sign as a lone commuter waits beneath the bus shelter, headphones on, watching puddles ripple. This atmospheric pixel piece proves that low resolution can carry high emotion: reflections stretch across wet asphalt in shimmering vertical bands, a vending machine glows softly at frame\'s edge, and a cat shelters under the bench. The restrained palette of slate blues and sodium-lamp ambers creates a mood of gentle melancholy — the feeling of a long day ending and the quiet comfort of being alone with your thoughts. Animated-style rain layering, frozen in a single perfect frame, gives the still image a sense of living time.', '蛍光灯の看板がにじむ雨の夜、バス停の下でヘッドホンをつけてバスを待つ一人の通勤者。一ドットの雨の筋、濡れたアスファルトに伸びる光の反射、隅で光る自動販売機、ベンチの下で雨宿りする猫。青とオレンジの抑えた色調が、一日の終わりの静かな安らぎと心地よい孤独を表現します。低解像度に深い感情を宿した、叙情的なドット絵作品です。', 'Pixel Rain at the Bus Stop', 'Moody pixel art rainy night bus stop scene with atmospheric lighting', 'pixel rain art, rainy night pixel scene, moody pixel artwork, bus stop illustration, lofi pixel art print', 'storage/photos/products/12.webp', 999999, NULL, NULL, 'active', 31.00, 31, 31.00, 31.00, 0.00, 0, '', '', 2, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(13, 'Bubblegum Icon', 'バブルガム・アイコン', 'bubblegum-icon', 'A bold pop art portrait of a retro girl blowing a giant pink bubblegum bubble in halftone style.', 'ハーフトーンで描かれた、大きなピンクの風船ガムを膨らませるレトロガールのポップアート。', 'A perfect pink sphere of bubblegum dominates this high-impact pop art portrait, its glossy highlight rendered against a field of oversized halftone dots. The subject\'s cat-eye sunglasses reflect a comic-book cityscape, and her victory-rolled hair nods to 1960s advertising illustration. Thick black keylines, a strictly limited palette of bubblegum pink, canary yellow, and cyan, and deliberate print misregistration recreate the tactile charm of vintage screen printing. It is playful, confident, and instantly iconic — the kind of image that anchors a room. This piece distills the pop art formula: take a fleeting everyday pleasure, blow it up larger than life, and let color do the talking.', 'つややかなハイライトを持つ完璧なピンクの風船ガムが、大きなハーフトーンドットを背景に画面を支配するポップアートポートレート。キャットアイのサングラスにはコミック調の街並みが映り込み、レトロなヘアスタイルが60年代広告イラストへのオマージュとなっています。ピンク、イエロー、シアンの限定パレットと太い輪郭線が、ヴィンテージシルクスクリーンの魅力を再現。日常の小さな楽しみを大胆に拡大した、部屋の主役になる一枚です。', 'Bubblegum Icon Pop Art', 'Bold halftone pop art portrait with giant pink bubblegum bubble', 'pop art portrait, bubblegum artwork, halftone digital art, retro pop illustration, 60s style pop print', 'storage/photos/products/13.webp', 999999, NULL, NULL, 'active', 39.00, 39, 39.00, 39.00, 0.00, 1, '', '', 3, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(14, 'Comic Panel Explosion', 'コミックパネルの爆発', 'comic-panel-explosion', 'A dynamic pop art piece bursting with comic panels, sound-effect lettering, and Ben-Day dots.', 'コミックのコマ割りと擬音レタリング、ベンデイドットが弾けるダイナミックなポップアート作品。', 'WHAM! ZAP! POW! Hand-lettered sound effects explode across a grid of comic panels that shatter outward from the center of this kinetic pop artwork. Each fragment holds a different scene — a speeding car, a dramatic close-up of eyes, a rotary phone mid-ring — telling a story the viewer assembles themselves. Ben-Day dots in graduated sizes create the signature texture of mid-century comic printing, while jagged starburst frames and speed lines drive the eye around the composition in an endless loop. The primary-color palette hits with maximum punch: fire-engine red, cobalt, and taxi yellow against crisp white. A celebration of comic book visual language, engineered for pure graphic energy.', '手描きの擬音レタリングが弾け、中心から外へ砕け散るコミックパネルのグリッド。疾走する車、印象的な瞳のクローズアップ、鳴り響く電話——各コマが異なる場面を描き、鑑賞者自身が物語を組み立てます。ベンデイドットが往年のコミック印刷の質感を再現し、集中線が視線を画面中で循環させます。赤・青・黄の原色が最大限のインパクトを放つ、コミック的視覚言語の祝祭です。', 'Comic Panel Explosion', 'Dynamic pop art with comic panels, sound effects, and Ben-Day dots', 'comic pop art, ben day dots artwork, comic panel illustration, pop art explosion print, retro comic digital art', 'storage/photos/products/14.webp', 999999, NULL, NULL, 'active', 37.00, 37, 37.00, 37.00, 0.00, 1, '', '', 3, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(15, 'Canned Nostalgia', '缶詰のノスタルジア', 'canned-nostalgia', 'A pop art grid of colorful fictional vintage cans, each label a tiny design of its own.', '架空のヴィンテージ缶詰をカラフルに並べた、ラベルデザインが楽しいポップアートグリッド。', 'Sixteen fictional tin cans stand in a perfect grid, each wearing a lovingly designed vintage label: Cloud Soup, Instant Courage, Grandma\'s Thunder, Canned Sunshine. This pop art piece plays with the movement\'s fascination with consumer packaging while inventing an entirely imaginary supermarket shelf. Every label is a complete miniature design — typography, mascot, net weight and all — rendered in the saturated inks and slight print offsets of mid-century lithography. Repetition with variation gives the grid its hypnotic rhythm; the eye keeps returning to compare details. Wry, warm, and endlessly browsable, it turns the ordinary act of grocery shopping into a gallery of small joys.', '「雲のスープ」「即席の勇気」「缶詰の陽だまり」——架空のヴィンテージ缶詰16個が完璧なグリッドに並びます。ポップアートが愛した消費社会のパッケージデザインを、完全に想像上のスーパーの棚として再構築した作品です。各ラベルはタイポグラフィ、マスコット、内容量まで作り込まれた小さなデザインの完成形。反復と変化が生むリズムが、見る者の目を何度も引き戻します。日常の買い物を小さな喜びのギャラリーに変える一枚です。', 'Canned Nostalgia Pop Art', 'Pop art grid of fictional vintage can labels in retro print style', 'pop art cans, vintage label artwork, retro packaging art, pop art grid print, consumer pop illustration', 'storage/photos/products/15.webp', 999999, NULL, NULL, 'active', 35.00, 35, 35.00, 35.00, 0.00, 0, '', '', 3, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(16, 'Polka Dot Diva', '水玉のディーヴァ', 'polka-dot-diva', 'A glamorous pop art portrait of a singer mid-note, swallowed by waves of colorful polka dots.', '色鮮やかな水玉の波に包まれ、熱唱する歌手を描いた華やかなポップアートポートレート。', 'Caught mid-high-note, a glamorous singer dissolves into cascading polka dots that ripple outward from her microphone like visible sound. This pop art portrait fuses fashion illustration with graphic pattern play: her sequined dress is built entirely from dots of shifting scale, and the background pattern bends around her silhouette as if her voice warps the very fabric of the print. A jubilant palette of tangerine, fuchsia, and turquoise keeps the energy at concert pitch. Deliberate flatness — no gradients, no soft shadows — honors the screen-print tradition while the composition\'s swirling movement feels thoroughly contemporary. A portrait of music itself, told in the universal language of the dot.', '高音を歌い上げる瞬間、歌手の姿はマイクから波紋のように広がる水玉へと溶けていきます。スパンコールのドレスは大きさの異なるドットだけで構成され、背景のパターンは彼女の声に歪められるかのようにシルエットに沿って湾曲します。タンジェリン、フューシャ、ターコイズの陽気なパレットがコンサートの熱量を保ち、グラデーションを排した平面的表現がシルクスクリーンの伝統に敬意を表します。音楽そのものを水玉の言語で描いたポートレートです。', 'Polka Dot Diva', 'Glamorous pop art singer portrait built from colorful polka dot patterns', 'polka dot pop art, singer portrait artwork, music pop illustration, dot pattern digital art, glamour pop print', 'storage/photos/products/16.webp', 999999, NULL, NULL, 'active', 41.00, 41, 41.00, 41.00, 0.00, 0, '', '', 3, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(17, 'Retro Diner Milkshake', 'レトロダイナーのミルクセーキ', 'retro-diner-milkshake', 'A towering pop art milkshake in a chrome diner setting, dripping with 1950s Americana charm.', 'クロームが輝く50年代アメリカンダイナーを舞台に、そびえ立つミルクセーキを描いたポップアート。', 'A strawberry milkshake rises like a monument from a chrome counter, its whipped cream summit crowned with a cherry that gleams like a jewel. Behind it, the visual vocabulary of the classic American diner unfolds in flat, punchy color: checkerboard floor, neon OPEN sign, a jukebox glowing in the corner, red vinyl stools receding in perfect perspective. This pop art piece supersizes a humble pleasure with the reverence usually reserved for portraiture, complete with dramatic spotlight halo and halftone shading on the frosted glass. The palette is pure 1950s optimism — cherry red, cream, mint green, and chrome silver. Sweet, bold, and irresistibly nostalgic.', 'クロームのカウンターから記念碑のようにそびえるストロベリーミルクセーキ。ホイップクリームの頂には宝石のように輝くチェリー。市松模様の床、ネオンサイン、光るジュークボックス、赤いビニールのスツール——アメリカンダイナーの視覚言語がフラットで力強い色彩で展開されます。チェリーレッド、クリーム、ミントグリーン、シルバーの50年代らしい楽観的なパレットで、ささやかな喜びを堂々と讃える一枚です。', 'Retro Diner Milkshake', '1950s pop art milkshake artwork in a classic American diner scene', 'diner pop art, milkshake artwork, 50s americana print, retro diner illustration, vintage pop digital art', 'storage/photos/products/17.webp', 999999, NULL, NULL, 'active', 34.00, 34, 34.00, 34.00, 0.00, 0, '', '', 3, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(18, 'Halftone Sunset Drive', 'ハーフトーンの夕陽ドライブ', 'halftone-sunset-drive', 'A convertible cruises into a giant halftone sun in this cinematic pop art tribute to the open road.', '巨大なハーフトーンの太陽へ向かって走るオープンカーを描いた、映画的なポップアート作品。', 'Top down, radio up: a pastel convertible glides along a coastal highway straight into a colossal setting sun built from perfectly graduated halftone dots. Palm silhouettes strobe past in flat black, and the ocean is a field of horizontal cyan bands that vibrate against the sun\'s hot gradient of yellow through crimson. This pop art piece borrows the language of vintage travel posters and drive-in movie screens, compressing an entire feeling — freedom, summer, the last golden hour of a perfect day — into pure graphic shorthand. Motion lines trail from the chrome bumper, and the license plate reads a single word: LATER. Cool, effortless, and made to be framed large.', '屋根を開け、ラジオを上げて——パステルカラーのオープンカーが海岸道路を、完璧なグラデーションのハーフトーンドットで組み上げられた巨大な夕陽へと走ります。フラットな黒のヤシの木のシルエット、シアンの横縞で表現された海が、黄から深紅へ移ろう太陽と共鳴します。ヴィンテージ旅行ポスターとドライブインシアターの言語を借りて、自由と夏の黄金の時間をグラフィックに凝縮。大きく飾りたくなる、クールで爽快な一枚です。', 'Halftone Sunset Drive', 'Pop art convertible driving into a giant halftone sunset on a coastal road', 'halftone sunset art, pop art car print, retro travel poster art, coastal drive illustration, summer pop artwork', 'storage/photos/products/18.webp', 999999, NULL, NULL, 'active', 43.00, 43, 43.00, 43.00, 0.00, 1, '', '', 3, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(19, 'Wildstyle Alley', 'ワイルドスタイル・アレイ', 'wildstyle-alley', 'A back alley transformed by explosive wildstyle graffiti lettering in electric interlocking colors.', 'エレクトリックな色彩が絡み合うワイルドスタイルのグラフィティで埋め尽くされた路地裏。', 'Arrows, spikes, and interlocking letterforms twist across a brick wall in this celebration of wildstyle — graffiti\'s most complex and virtuosic lettering tradition. The piece layers electric blue, toxic green, and hot magenta with crisp 3D drop shadows and chrome fill effects, honoring techniques developed over decades of aerosol craft. Around the burner, the alley itself tells stories: overlapping tags, a dripping throw-up half covered, paint cans clustered at the wall\'s base, and a ladder still leaning where the artist left it. Light from a single caged bulb rakes across the texture of brick and drip. It is a portrait of graffiti as living dialogue — walls that never stop talking.', '矢印、スパイク、絡み合うレターフォームがレンガの壁を駆け抜ける——グラフィティで最も複雑で技巧的なワイルドスタイルへの賛歌です。エレクトリックブルー、トキシックグリーン、ホットマゼンタが立体的なドロップシャドウとクローム効果で重なり合います。壁の周囲では、重なるタグ、描きかけの作品、壁際に集められたスプレー缶、立てかけられたままの脚立が物語を紡ぎます。決して語ることをやめない壁——生きた対話としてのグラフィティの肖像です。', 'Wildstyle Alley', 'Explosive wildstyle graffiti lettering artwork in an urban back alley', 'wildstyle graffiti art, urban lettering artwork, spray paint digital art, graffiti alley print, street lettering illustration', 'storage/photos/products/19.webp', 999999, NULL, NULL, 'active', 38.00, 38, 38.00, 38.00, 0.00, 1, '', '', 4, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(20, 'Stencil Revolution', 'ステンシル・レボリューション', 'stencil-revolution', 'A striking multi-layer stencil artwork of a girl releasing paper planes that turn into doves.', '紙飛行機を飛ばす少女——それはやがて鳩へと変わる。多層ステンシルで描かれた印象的な作品。', 'Cut in crisp multi-layer stencil style against raw concrete, a young girl releases a squadron of paper planes that transform, one by one, into white doves as they climb the wall. The piece speaks in street art\'s most democratic dialect: high-contrast black portraiture softened by a single accent of red on the girl\'s scarf, with drips left deliberately unretouched as a signature of the medium. The concrete texture shows through every layer, weathered and honest. The metamorphosis from folded paper to living wings reads as a quiet manifesto about imagination outgrowing its origins. Minimal in means, maximal in resonance — the essence of great stencil work brought to digital form.', '打ちっぱなしのコンクリートに、多層ステンシルで切り抜かれた少女。彼女が放つ紙飛行機は、壁を昇るにつれて一羽ずつ白い鳩へと姿を変えていきます。ハイコントラストの黒い人物像に、スカーフの赤がただ一点のアクセント。あえて残された塗料の垂れが、この表現手法の署名となっています。折り紙から生きた翼への変容は、想像力がその起源を超えて羽ばたくという静かな宣言。最小の手段で最大の共鳴を生む、ステンシルアートの真髄です。', 'Stencil Revolution', 'Multi-layer stencil street art of a girl releasing paper planes turning into doves', 'stencil street art, urban stencil artwork, concrete wall art print, dove graffiti illustration, political street art', 'storage/photos/products/20.webp', 999999, NULL, NULL, 'active', 40.00, 40, 40.00, 40.00, 0.00, 1, '', '', 4, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(21, 'Spray Can Symphony', 'スプレー缶シンフォニー', 'spray-can-symphony', 'A surreal street art piece where spray cans pour rivers of paint that form a city skyline.', 'スプレー缶から流れ出す絵の具の川が、やがて都市のスカイラインを形づくるシュールな作品。', 'Suspended in formation like instruments in an orchestra, a dozen spray cans pour streams of liquid color that flow, merge, and rise into the silhouette of a city skyline. Each paint river keeps its pigment identity — crimson becoming a tower, gold becoming a bridge — until the skyline reads as a city literally built from paint. The style fuses photoreal can renders with loose, expressive splatter, mirroring street art\'s own collision of precision and chaos. Fine mist particles and pressure-drip details show deep respect for the tool at the culture\'s heart. Set against a deep charcoal background, the colors achieve stained-glass luminosity. A tribute to the simple can that painted whole cities into galleries.', 'オーケストラの楽器のように整列した十数本のスプレー缶から、液状の色彩が流れ出し、混ざり合い、やがて都市のスカイラインへと立ち上がります。深紅は塔に、金は橋に——絵の具そのもので築かれた街。写実的な缶の描写と自由奔放なスプラッターの融合は、精密と混沌が衝突するストリートアートの本質を映します。チャコールの背景に色彩がステンドグラスのように輝く、街全体をギャラリーに変えたスプレー缶への賛辞です。', 'Spray Can Symphony', 'Surreal street art of spray cans pouring paint rivers that form a city skyline', 'spray can artwork, surreal street art, paint city illustration, graffiti concept print, urban art digital', 'storage/photos/products/21.webp', 999999, NULL, NULL, 'active', 42.00, 42, 42.00, 42.00, 0.00, 0, '', '', 4, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(22, 'Brick Wall Bloom', 'レンガ壁に咲く花', 'brick-wall-bloom', 'A mural-style artwork of giant painted flowers bursting through cracks in an old brick wall.', '古いレンガ壁のひび割れから咲き誇る、巨大な花々を描いた壁画スタイルの作品。', 'From a jagged crack in a weathered brick wall, enormous painted flowers erupt in defiant color — sunflowers, poppies, and morning glories rendered in bold mural style with aerosol-soft gradients and confident brushed outlines. The conceit is beautifully literal: where the wall breaks, life gets in. Painted petals cast painted shadows, and a few painted bees hover in trompe-l\'oeil space, blurring the line between wall and world. Below, at street level, real weeds growing from the pavement mirror the mural above in a quiet visual rhyme. The palette pits warm botanical oranges and pinks against cool brick reds and mortar greys. Urban decay and stubborn beauty, holding each other up.', '風化したレンガ壁のひび割れから、ヒマワリ、ポピー、アサガオが反骨の色彩で咲き乱れます。エアゾールの柔らかなグラデーションと力強い輪郭線による大胆な壁画スタイル。壁が壊れた場所から、命が入り込む——描かれた花びらは描かれた影を落とし、だまし絵のように飛ぶ蜂が壁と現実の境界を曖昧にします。足元では舗道から伸びる本物の雑草が、壁の上の壁画と静かに呼応します。都市の荒廃と、それでも咲く美しさが支え合う作品です。', 'Brick Wall Bloom', 'Mural street art of giant flowers bursting through cracks in a brick wall', 'flower mural art, brick wall artwork, urban bloom illustration, street mural print, botanical graffiti art', 'storage/photos/products/22.webp', 999999, NULL, NULL, 'active', 37.00, 37, 37.00, 37.00, 0.00, 0, '', '', 4, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(23, 'Subway Car Chronicles', '地下鉄車両クロニクル', 'subway-car-chronicles', 'A retro-inspired artwork of a fully painted subway car rolling through a golden morning cityscape.', '朝焼けの都市を走る、全面ペイントされた地下鉄車両を描いたレトロインスパイアの作品。', 'An elevated train emerges into golden morning light, every inch of its steel skin transformed into a rolling canvas of pieces, characters, and blazing color. This artwork honors the legendary era when whole-car painting turned transit systems into the world\'s largest moving galleries — reimagined here as pure homage with entirely original lettering and characters. Sunlight flares off the windows between bursts of color, commuters on the platform turn to look, and pigeons scatter from the third rail\'s hum. The composition freezes the exact moment the train breaks from tunnel darkness into daylight: art built in secret, revealed to the whole city at once. Painted history in motion.', '朝焼けの光の中へ現れる高架鉄道——鋼鉄の車体は隅々まで、文字とキャラクターと燃える色彩の走るキャンバスへと変貌しています。地下鉄全体が世界最大の移動ギャラリーとなった伝説の時代への、完全オリジナルのレタリングによるオマージュ。窓に反射する陽光、振り返るホームの通勤客、飛び立つ鳩。トンネルの闇から日の光へと列車が飛び出す瞬間——秘密裏に生まれた芸術が、街全体に一斉に披露される瞬間を封じ込めました。', 'Subway Car Chronicles', 'Retro street art tribute of a fully painted subway train in morning light', 'subway graffiti art, painted train artwork, urban transit art print, retro graffiti illustration, train street art', 'storage/photos/products/23.webp', 999999, NULL, NULL, 'active', 45.00, 45, 45.00, 45.00, 0.00, 0, '', '', 4, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(24, 'The Masked Muralist', '覆面の壁画師', 'the-masked-muralist', 'A cinematic night scene of an anonymous artist finishing a towering mural by streetlight.', '街灯の光の下、そびえ立つ壁画を仕上げる名もなき覆面アーティストの映画的な夜のシーン。', 'Three stories up on a swaying scaffold, an anonymous figure in a respirator adds the final highlight to a towering mural of a phoenix, working by streetlight and headlamp while the city sleeps. The artwork-within-the-artwork glows nearly finished — fiery wings spanning the building\'s whole face — while the artist remains a small dark silhouette, deliberately unknowable. Cool blue night tones wrap the scene, broken by the mural\'s warm oranges and the lone amber cone of the streetlamp. Scattered cans, a rolled sketch, and a thermos on the scaffold plank humanize the labor behind the spectacle. It is a portrait of street art\'s central paradox: monumental public beauty, made by someone who vanishes before dawn.', '揺れる足場の三階分の高さで、レスピレーターをつけた名もなき人物が、街灯とヘッドランプの明かりを頼りに巨大な不死鳥の壁画へ最後のハイライトを加えます。建物の全面に広がる炎の翼はほぼ完成——しかし作者は小さな黒いシルエットのまま、意図的に匿名です。夜の青いトーンを、壁画の暖色と街灯の琥珀色が破ります。散らばる缶、丸めたスケッチ、足場の上の魔法瓶が、壮観の裏にある労働を物語ります。夜明け前に消える誰かが生む、記念碑的な公共の美——ストリートアートの逆説の肖像です。', 'The Masked Muralist', 'Cinematic night artwork of an anonymous street artist finishing a phoenix mural', 'muralist artwork, street artist night scene, phoenix mural art, urban artist illustration, anonymous artist print', 'storage/photos/products/24.webp', 999999, NULL, NULL, 'active', 46.00, 46, 46.00, 46.00, 0.00, 1, '', '', 4, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(25, 'Neo Wave over Shibuya', '渋谷に打ち寄せる新浪', 'neo-wave-over-shibuya', 'A modern ukiyo-e woodblock-style wave crashes over the Shibuya crossing in a bold heritage remix.', '浮世絵の大波が渋谷のスクランブル交差点に打ち寄せる、大胆な伝統リミックス作品。', 'A colossal indigo wave, rendered in classic woodblock style with clawing white foam, rears over the world\'s busiest pedestrian crossing while tiny umbrella-carrying figures scatter below like Edo-period travelers. This modern ukiyo-e piece stages a conversation across three centuries: traditional bokashi gradient skies meet glowing crosswalk signals, and the wave\'s linework follows historical carving conventions down to the layered registration of each color. Billboard frames stand empty, becoming abstract golden rectangles that echo the format of old print cartouches. The palette holds to authentic mineral pigments — Prussian blue, ochre, soft beni red — proving the old visual grammar can describe the newest city on earth.', '鉤爪のような白い波頭を持つ藍色の大波が、木版画の様式で世界一混雑する交差点に襲いかかり、傘を差した小さな人々が江戸の旅人のように行き交います。伝統的なぼかしの空と光る信号機が、三世紀を越えた対話を交わす現代浮世絵。波の線描は彫師の伝統に忠実に、色の重なりは版の見当合わせを再現しています。プルシアンブルー、黄土、紅の顔料に徹した色彩が、古の視覚文法で最新の都市を描けることを証明する一枚です。', 'Neo Wave over Shibuya', 'Modern ukiyo-e woodblock wave artwork crashing over Shibuya crossing', 'modern ukiyoe art, japanese wave artwork, shibuya woodblock print, neo japanese illustration, wave city art', 'storage/photos/products/25.webp', 999999, NULL, NULL, 'active', 48.00, 48, 48.00, 48.00, 0.00, 1, '', '', 5, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(26, 'Crimson Torii at Dawn', '暁の紅い鳥居', 'crimson-torii-at-dawn', 'A serene ukiyo-e style artwork of a thousand vermilion torii gates winding up a misty mountain at dawn.', '暁の霧に包まれた山を縫うように連なる千本の朱い鳥居を描いた、静謐な浮世絵風作品。', 'A corridor of vermilion torii gates climbs a mountainside through layers of dawn mist, each gate rendered with the flat, confident color and precise outline of traditional woodblock printing. The path curves out of sight, inviting the eye on a pilgrimage it can never complete — a compositional device beloved by the old masters. Bokashi gradients shift the sky from pale rose at the horizon to deep slate above, while a single fox sits at the first gate, keeper of the threshold. The repeating geometry of the gates creates a hypnotic rhythm broken only by stone lanterns and moss-softened steps. Reverent, meditative, and steeped in the visual language of classic Japanese landscape prints.', '暁の霧が幾重にも立ち込める山肌を、朱塗りの鳥居の回廊が登っていきます。一基一基が、伝統木版画の平坦で力強い色面と精緻な輪郭で描かれています。参道は視界の外へと曲がり、決して終わらぬ巡礼へと目を誘う——古の絵師たちが愛した構図の妙。空はぼかしの技法で、地平の薄紅から頭上の深い藍鼠へと移ろいます。最初の鳥居には一匹の狐が、結界の番人として座しています。荘厳で瞑想的な、古典的日本風景版画の様式美に満ちた作品です。', 'Crimson Torii at Dawn', 'Ukiyo-e style artwork of a thousand torii gates on a misty mountain at dawn', 'torii gate artwork, ukiyoe landscape print, japanese shrine art, vermilion gates illustration, woodblock style art', 'storage/photos/products/26.webp', 999999, NULL, NULL, 'active', 44.00, 44, 44.00, 44.00, 0.00, 1, '', '', 5, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(27, 'Koi Beneath the Paper Moon', '紙の月と鯉', 'koi-beneath-the-paper-moon', 'Two koi circle beneath a full moon\'s reflection in this elegant modern woodblock-style artwork.', '満月の映る水面の下で円を描く二匹の鯉を、優雅な現代木版画スタイルで表現した作品。', 'On a pond as black as lacquer, the full moon lays down a perfect pale circle — and beneath it, two koi turn in an eternal slow orbit, one white with red, one deep gold. This modern ukiyo-e composition reduces the night to essentials: fish, moon, water, and a few drifting maple leaves, each element outlined with the calligraphic precision of a master carver\'s key block. Stylized ripple rings expand in flat concentric bands, and the koi\'s scales are patterned like textile design, honoring the print tradition\'s love of ornament within realism. The restraint is total, the effect hypnotic. A meditation on movement and stillness, rendered in the quietest possible palette of ink, gold, and moonlight.', '漆黒の池の面に、満月が完璧な淡い円を落とし——その下で二匹の鯉が永遠の緩やかな軌道を描きます。紅白と山吹の二匹。魚、月、水、そして流れる数枚の紅葉だけに夜を還元した現代浮世絵の構図。各要素は名匠の主版のような書道的精密さで輪郭づけられています。様式化された波紋が平坦な同心円で広がり、鯉の鱗は織物のような文様で描かれ、写実の中の装飾を愛する版画の伝統に敬意を表します。墨と金と月光だけの静謐なパレットによる、動と静の瞑想です。', 'Koi Beneath the Paper Moon', 'Modern woodblock-style artwork of two koi circling under a full moon reflection', 'koi woodblock art, japanese moon artwork, koi pond illustration, modern ukiyoe print, zen japanese art', 'storage/photos/products/27.webp', 999999, NULL, NULL, 'active', 46.00, 46, 46.00, 46.00, 0.00, 0, '', '', 5, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(28, 'Geisha with Headphones', 'ヘッドホンの芸者', 'geisha-with-headphones', 'A playful modern ukiyo-e portrait of a geisha in full traditional dress wearing glowing headphones.', '伝統的な装いの芸者が光るヘッドホンをつける、遊び心あふれる現代浮世絵ポートレート。', 'Rendered in the refined bijin-ga portrait tradition, a geisha in an exquisitely patterned kimono tilts her head to the music flowing through a pair of softly glowing headphones. Every classical element is honored — the elaborate shimada hairstyle, the kanzashi ornaments, the layered collar lines drawn with a single perfect stroke — and then gently subverted by the one anachronism she wears with complete serenity. The kimono pattern itself hides tiny cassette tapes and equalizer bars among traditional waves and chrysanthemums, rewarding the patient eye. Flat color fields, mica-dust background shimmer, and woodgrain texture complete the print authenticity. A witty, affectionate bridge between the floating world and the streaming one.', '美人画の伝統に則って描かれた芸者が、柔らかく光るヘッドホンから流れる音楽に耳を傾けます。島田髷、簪、一筆で描かれた襟元の重なり——古典の要素をすべて丁寧に守りながら、彼女が纏うただ一つの時代錯誤が静かに伝統を裏切ります。着物の柄には、波と菊の伝統文様に紛れて小さなカセットテープとイコライザーが隠されており、丹念に見る者への贈り物となっています。雲母摺りの背景と木目のテクスチャが版画の本物らしさを完成させる、浮世とストリーミングの世界を結ぶ機知に富んだ一枚です。', 'Geisha with Headphones', 'Playful modern ukiyo-e geisha portrait with glowing headphones', 'modern geisha art, ukiyoe portrait print, japanese fusion artwork, bijinga modern art, geisha illustration', 'storage/photos/products/28.webp', 999999, NULL, NULL, 'active', 47.00, 47, 47.00, 47.00, 0.00, 1, '', '', 5, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(29, 'Fuji and the Vending Machine', '富士と自動販売機', 'fuji-and-the-vending-machine', 'Mount Fuji rises behind a lone glowing vending machine on a country road in ukiyo-e style.', '田舎道にぽつんと光る自動販売機の向こうに富士山がそびえる、浮世絵スタイルの作品。', 'On an empty country road at blue hour, a single vending machine glows like a paper lantern — and behind it, framed exactly as the old masters framed it, Mount Fuji rises snow-capped into a gradient sky. This modern ukiyo-e piece joins the centuries-long tradition of \'views of Fuji\' by adding the view every Japanese traveler actually knows: the faithful roadside machine humming in the middle of nowhere. Woodblock conventions govern everything — flat color planes, outlined telephone poles receding in rhythmic diminution, stylized pampas grass in the foreground breeze. The machine\'s product rows are tiny abstract color chips, like a modern pigment chart offered to the mountain. Humble, humorous, and quietly profound.', '人けのない田舎道の青い黄昏時、一台の自動販売機が行灯のように光り——その向こうには、古の絵師たちが額装したのと同じ構図で、雪を頂く富士山がグラデーションの空にそびえます。何世紀にもわたる「富士見」の伝統に、現代の日本の旅人が誰でも知る風景——人里離れた場所で健気に唸る自販機——を加えた現代浮世絵。平坦な色面、律動的に遠ざかる電柱、風にそよぐ様式化されたススキ。自販機の商品列は、山に捧げられた現代の顔料見本のような小さな色片です。慎ましく、ユーモラスで、静かに深遠な作品です。', 'Fuji and the Vending Machine', 'Modern ukiyo-e artwork of Mount Fuji behind a glowing roadside vending machine', 'mount fuji artwork, modern ukiyoe print, japanese vending machine art, fuji woodblock illustration, japan countryside art', 'storage/photos/products/29.webp', 999999, NULL, NULL, 'active', 45.00, 45, 45.00, 45.00, 0.00, 0, '', '', 5, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
(30, 'Snow Country Lantern Walk', '雪国の灯籠歩き', 'snow-country-lantern-walk', 'Villagers with paper lanterns cross a snowy bridge at night in this tranquil woodblock-style scene.', '雪の夜、紙灯籠を手に橋を渡る村人たちを描いた静謐な木版画スタイルの情景。', 'Snow falls in perfect woodblock flecks as a procession of villagers crosses an arched wooden bridge, their paper lanterns hanging warm orange pools in the blue-grey night. This modern ukiyo-e scene draws on the great snow prints of the tradition: thatched roofs wearing thick white caps, a river running ink-dark below, and bare willow branches sketched in the fewest possible strokes. Each figure huddles into a differently patterned winter kimono, tiny studies in textile design. The bokashi sky deepens from charcoal at the top to a faint lantern-glow horizon, and the falling snow is scattered with deliberate irregularity, the way a printer would flick pigment from a brush. Silent, warm-hearted, and timeless.', '木版画特有の雪片が舞い落ちる中、村人たちの行列が太鼓橋を渡り、紙灯籠が青灰色の夜に温かな橙の光の輪を灯します。厚い雪の帽子をかぶった茅葺き屋根、墨色に流れる川、最小限の筆致で描かれた裸の柳——伝統の雪景色版画の系譜に連なる現代浮世絵です。一人一人が異なる文様の冬着に身を包み、それぞれが小さな織物デザインの習作となっています。ぼかしの空は上部の炭色から灯籠の光がにじむ地平へと深まり、舞う雪は摺師が刷毛から顔料を弾くように意図的な不規則さで散らされています。静かで、心温まる、時を超えた一枚です。', 'Snow Country Lantern Walk', 'Tranquil woodblock-style artwork of lantern-carrying villagers on a snowy bridge', 'japanese snow artwork, lantern night print, winter ukiyoe art, snowy village illustration, woodblock snow scene', 'storage/photos/products/30.webp', 999999, NULL, NULL, 'active', 43.00, 43, 43.00, 43.00, 0.00, 0, '', '', 5, NULL, NULL, '0', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL);
